//! Session-local mutex plus a bounded, invisible Win32 message-only receiver.
//! No socket, service, registry change or simulated user input is involved.
use crate::launch::{Packet,Pending,MAX_PACKET};use std::{sync::{Arc,mpsc,atomic::{AtomicBool,Ordering}},thread,time::{Duration,Instant},io,path::PathBuf};
use windows_sys::Win32::{Foundation::{CloseHandle,GetLastError,HANDLE,HWND,LPARAM,WPARAM,LRESULT,ERROR_ALREADY_EXISTS},System::{Threading::{CreateMutexW,OpenProcess,QueryFullProcessImageNameW,PROCESS_QUERY_LIMITED_INFORMATION},LibraryLoader::GetModuleHandleW,DataExchange::COPYDATASTRUCT},UI::WindowsAndMessaging::*};
const MAGIC:usize=0x50444601;
fn wide(s:&str)->Vec<u16>{s.encode_utf16().chain(Some(0)).collect()}
fn executable(hwnd:HWND)->Option<PathBuf>{let mut pid=0;unsafe{GetWindowThreadProcessId(hwnd,&mut pid);}if pid==0{return None;}let process=unsafe{OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,0,pid)};if process.is_null(){return None;}let mut data=vec![0u16;32768];let mut length=data.len()as u32;let ok=unsafe{QueryFullProcessImageNameW(process,0,data.as_mut_ptr(),&mut length)};unsafe{CloseHandle(process);}if ok==0{return None;}Some(PathBuf::from(String::from_utf16(&data[..length as usize]).ok()?))}
fn same_executable(a:&std::path::Path,b:&std::path::Path)->bool{a.to_string_lossy().eq_ignore_ascii_case(&b.to_string_lossy())}
struct Receiver{pending:Arc<Pending>,exe:PathBuf,stopped:Arc<AtomicBool>}
unsafe extern "system" fn procedure(hwnd:HWND,msg:u32,w:WPARAM,l:LPARAM)->LRESULT{
 if msg==WM_CREATE{if GetWindowLongPtrW(hwnd,GWLP_USERDATA)!=0||l==0{return -1;}let create=&*(l as *const CREATESTRUCTW);SetWindowLongPtrW(hwnd,GWLP_USERDATA,create.lpCreateParams as isize);return 0;}
 if msg==WM_NULL{let receiver=GetWindowLongPtrW(hwnd,GWLP_USERDATA)as *const Receiver;if !receiver.is_null()&&(*receiver).stopped.load(Ordering::Acquire){DestroyWindow(hwnd);}return 0;}
 if msg==WM_CLOSE{return 0;}if msg==WM_DESTROY{if GetWindowLongPtrW(hwnd,GWLP_USERDATA)!=0{PostQuitMessage(0);}return 0;}
 if msg!=WM_COPYDATA{return DefWindowProcW(hwnd,msg,w,l);}
 // WM_COPYDATA is copied by Windows across the process boundary. Validate its
 // explicit byte length before making a slice; never use unbounded C strings.
 std::panic::catch_unwind(||{let receiver=GetWindowLongPtrW(hwnd,GWLP_USERDATA)as *const Receiver;if receiver.is_null()||l==0||w==0{return 0;}let receiver=&*receiver;if receiver.stopped.load(Ordering::Acquire){return 0;}let data=&*(l as *const COPYDATASTRUCT);if data.dwData!=MAGIC||data.cbData==0||data.cbData as usize>MAX_PACKET||data.lpData.is_null(){return 0;}let Some(peer)=executable(w as HWND)else{return 0;};if !same_executable(&peer,&receiver.exe){return 0;}let bytes=std::slice::from_raw_parts(data.lpData as *const u8,data.cbData as usize);match Packet::decode(bytes).and_then(|p|receiver.pending.push(p)){Ok(())=>1,Err(_)=>0}}).unwrap_or(0)
}
fn make_window(class:&[u16],receiver:*const Receiver)->io::Result<HWND>{unsafe{let module=GetModuleHandleW(std::ptr::null());let mut entry=WNDCLASSEXW::default();entry.cbSize=std::mem::size_of::<WNDCLASSEXW>()as u32;entry.lpfnWndProc=Some(procedure);entry.hInstance=module;entry.lpszClassName=class.as_ptr();if RegisterClassExW(&entry)==0&&GetLastError()!=1410{return Err(io::Error::last_os_error());}let hwnd=CreateWindowExW(0,class.as_ptr(),class.as_ptr(),0,0,0,0,0,HWND_MESSAGE,std::ptr::null_mut(),module,receiver as _);if hwnd.is_null(){return Err(io::Error::last_os_error());}Ok(hwnd)}}
pub struct Instance{handle:HANDLE,hwnd:isize,stopped:Arc<AtomicBool>,thread:Option<thread::JoinHandle<()>>}
impl Instance{
 pub fn acquire(pending:Arc<Pending>,packet:&Packet)->io::Result<Option<Self>>{let mode=if cfg!(debug_assertions){"debug"}else{"release"};Self::named(&format!("Local\\io.github.ainativepdfreader.{mode}.routing-v1"),pending,packet)}
 fn named(name:&str,pending:Arc<Pending>,packet:&Packet)->io::Result<Option<Self>>{
  let exe=std::env::current_exe()?;let mutex=wide(name);let handle=unsafe{CreateMutexW(std::ptr::null(),0,mutex.as_ptr())};if handle.is_null(){return Err(io::Error::last_os_error());}let duplicate=unsafe{GetLastError()}==ERROR_ALREADY_EXISTS;let class=wide(&name.replace('\\',"-"));
  if duplicate{unsafe{CloseHandle(handle);}let deadline=Instant::now()+Duration::from_secs(3);let target=loop{let h=unsafe{FindWindowExW(HWND_MESSAGE,std::ptr::null_mut(),class.as_ptr(),class.as_ptr())};if !h.is_null(){break h;}if Instant::now()>deadline{return Err(io::Error::new(io::ErrorKind::TimedOut,"Existing reader receiver is not ready"));}thread::sleep(Duration::from_millis(10));};if !executable(target).is_some_and(|p|same_executable(&p,&exe)){return Err(io::Error::new(io::ErrorKind::PermissionDenied,"Another reader binary is running; close it first"));}
   let bytes=packet.encode().map_err(io::Error::other)?;let sender=make_window(&class,std::ptr::null())?;let data=COPYDATASTRUCT{dwData:MAGIC,cbData:bytes.len()as u32,lpData:bytes.as_ptr()as _};let mut result=0;let sent=unsafe{SendMessageTimeoutW(target,WM_COPYDATA,sender as usize,&data as *const _ as isize,SMTO_BLOCK|SMTO_ABORTIFHUNG,2000,&mut result)};unsafe{DestroyWindow(sender);}if sent==0||result!=1{return Err(io::Error::new(io::ErrorKind::Other,"Reader refused or timed out receiving PDF arguments"));}return Ok(None);
  }
  let stopped=Arc::new(AtomicBool::new(false));let stop=stopped.clone();let(tx,rx)=mpsc::sync_channel(1);let background=thread::spawn(move||{let receiver=Box::new(Receiver{pending,exe,stopped:stop});let hwnd=match make_window(&class,&*receiver){Ok(h)=>h,Err(e)=>{let _=tx.send(Err(e));return;}};if tx.send(Ok(hwnd as isize)).is_err(){unsafe{DestroyWindow(hwnd);}return;}if receiver.stopped.load(Ordering::Acquire){unsafe{DestroyWindow(hwnd);}return;}let mut msg=MSG::default();unsafe{while GetMessageW(&mut msg,std::ptr::null_mut(),0,0)>0{if receiver.stopped.load(Ordering::Acquire){break;}TranslateMessage(&msg);DispatchMessageW(&msg);}if IsWindow(hwnd)!=0{DestroyWindow(hwnd);}}drop(receiver);});
  match rx.recv_timeout(Duration::from_secs(3)){Ok(Ok(hwnd))=>Ok(Some(Self{handle,hwnd,stopped,thread:Some(background)})),other=>{stopped.store(true,Ordering::Release);unsafe{CloseHandle(handle);}Err(other.err().map(io::Error::other).unwrap_or_else(||io::Error::other("Receiver initialization failed")))}}
 }
}
impl Drop for Instance{fn drop(&mut self){self.stopped.store(true,Ordering::Release);unsafe{PostMessageW(self.hwnd as HWND,WM_NULL,0,0);}if let Some(thread)=self.thread.take(){let _=thread.join();}unsafe{CloseHandle(self.handle);}}}
#[cfg(test)]mod tests{
 use super::*;
 #[test]fn duplicate_instances_are_rejected_and_exit_releases_guard(){let name=format!("Local\\pdf-reader-test-{}",uuid::Uuid::new_v4());let q=Arc::new(Pending::default());let empty=Packet{schema:1,paths:vec![]};let first=Instance::named(&name,q.clone(),&empty).unwrap().unwrap();assert!(Instance::named(&name,Arc::new(Pending::default()),&empty).unwrap().is_none());assert!(q.focus_requested());drop(first);assert!(Instance::named(&name,q,&empty).unwrap().is_some());}
 #[test]#[ignore="private child entry, invoked by parent with --ignored"]fn m7_native_ipc_child(){let name=std::env::var("M7_PRIVATE_TEST_INSTANCE").expect("private parent required");let packet=Packet{schema:1,paths:vec![crate::save_core::project().join("tests/work/m7-prep/中文 空格.pdf").to_str().unwrap().into(),crate::save_core::project().join("tests/work/m7-prep/另一个.pdf").to_str().unwrap().into()]};let result=Instance::named(&name,Arc::new(Pending::default()),&packet);if std::env::var_os("M7_EXPECT_REFUSAL").is_some(){assert!(result.is_err());}else{assert!(result.unwrap().is_none());}}
 #[test]fn m7_closed_receiver_refuses_a_real_child_and_does_not_issue_grants(){let name=format!("Local\\pdf-reader-test-{}",uuid::Uuid::new_v4());let q=Arc::new(Pending::default());let empty=Packet{schema:1,paths:vec![]};let first=Instance::named(&name,q.clone(),&empty).unwrap().unwrap();q.close();assert!(q.push(Packet{schema:1,paths:vec![crate::save_core::project().join("tests/work/m7-prep/中文 空格.pdf").to_str().unwrap().into()]}).is_err());assert!(q.take(&crate::files::Files::default(),"main").is_err());let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","instance::tests::m7_native_ipc_child","--ignored","--nocapture"]).env("M7_PRIVATE_TEST_INSTANCE",&name).env("M7_EXPECT_REFUSAL","1").output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert!(q.queued_paths().is_empty());drop(first);}
 #[test]fn m7_real_child_process_forwards_two_unicode_paths_before_ui_is_ready(){let name=format!("Local\\pdf-reader-test-{}",uuid::Uuid::new_v4());let q=Arc::new(Pending::default());let empty=Packet{schema:1,paths:vec![]};let first=Instance::named(&name,q.clone(),&empty).unwrap().unwrap();let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","instance::tests::m7_native_ipc_child","--ignored","--nocapture"]).env("M7_PRIVATE_TEST_INSTANCE",&name).output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert!(q.focus_requested());let paths=q.queued_paths();assert_eq!(paths.len(),2);assert_eq!(paths[0],crate::save_core::project().join("tests/work/m7-prep/中文 空格.pdf"));assert_eq!(paths[1],crate::save_core::project().join("tests/work/m7-prep/另一个.pdf"));drop(first);}
}
